-- [Dashboard - Guide]
L["GUIDE_TITLE"] = "Быстрый старт"
L["GUIDE_SUBTITLE"] = "Настройте свой профиль OxedHub за три простых шага."
L["GUIDE_STEP1_TITLE"] = "1. Настройка триггеров"
L["GUIDE_STEP1_DESC"] = "Перейдите на вкладку Триггеры, чтобы точно указать условия срабатывания реакций. Вы можете задать триггеры для входа или выхода из боя, применения заклинаний, получения положительных или отрицательных эффектов, начала сражения с боссом или даже получения определенных сообщений в чате. Гибкая настройка условий позволяет создавать уникальные действия для любой игровой ситуации."
L["GUIDE_STEP2_TITLE"] = "2. Создание действий"
L["GUIDE_STEP2_DESC"] = "Определите, какие реакции будут происходить при срабатывании триггеров. Вы можете настроить воспроизведение звуковых файлов, исполнение эмоций персонажа, вывод экранных анимаций или автоматическую отправку сообщений в каналы чата (Сказать или Группа). В сочетании с триггерами вы можете создать полностью автоматизированный набор атмосферных эффектов для вашего персонажа!"
L["GUIDE_STEP3_TITLE"] = "3. Привязка кнопок"
L["GUIDE_STEP3_DESC"] = "Привязывайте заклинания, средства передвижения, игрушки или макросы напрямую к радиальным меню OxedRing или узлам ActionHub. Вы можете перетаскивать кнопки прямо из книги заклинаний или сумки, чтобы закрепить предметы для быстрого доступа, не захламляя панели команд."

-- [Dashboard - ActionHub Guide]
L["AH_GUIDE_TITLE"] = "Руководство ActionHub"
L["AH_GUIDE_SUBTITLE"] = "Узнайте, как использовать ActionHub в качестве\nдополнительной панели заклинаний и расширителя макросов."
L["AH_GUIDE_HOW_IT_WORKS"] = "Принцип работы"
L["AH_GUIDE_EXPLANATION"] = "• |cffffd100Безлимитные макросы:|r Создавайте и запускайте тысячи собственных скриптов, заклинаний, игрушек или эмоций, не занимая стандартные слоты персонажа в WoW. Все макросы безопасно выполняются внутри виртуальной машины OxedEngine.\n\n• |cffffd100Автоматизация на триггерах:|r Автоматизируйте действия, привязывая макросы напрямую к игровым триггерам. Движок мгновенно сканирует боевые события, заклинания и чат для их активации.\n\n• |cffffd100Дополнительная панель команд:|r Настраивайте расположение, размер и структуру узлов в любом месте экрана. Перетаскивайте предметы или заклинания, чтобы использовать модуль как отзывчивую панель действий."

