L["OR_GUIDE_EXPLANATION"] = "• |cffffd100Радиальные круговые меню:|r Назначьте клавишу для вызова отзывчивого визуального кругового меню команд прямо вокруг курсора мыши.\n\n• |cffffd100Удобная привязка:|r Перетаскивайте заклинания, средства передвижения, игрушки или макросы прямо из книги заклинаний или сумок в сектора кольца для их назначения.\n\n• |cffffd100Механика быстрого применения:|r Просто зажмите горячую клавишу, наведите курсор на нужный сектор и отпустите её для мгновенного выполнения действия."

