-- [About Tab]
L["ABOUT_WELCOME_TITLE"] = "Добро пожаловать в Oxed Hub!"
L["ABOUT_WELCOME_SUB"] = "Oxed Hub - это единый интерфейс, созданный для того, чтобы оживить ваш игровой процесс в World of Warcraft с помощью пользовательских триггеров и реакций."
L["ABOUT_CARD_FEATURES"] = "Возможности"
L["ABOUT_FEATURES_DESC"] = "• |cffffd100Собственные звуки:|r Воспроизведение локальных звуковых файлов в ответ на события.\n• |cffffd100Пользовательские анимации:|r Воспроизведение анимаций спрайт-листов TGA в любом месте экрана.\n• |cffffd100Эмоции:|r Автоматическое выполнение стандартных внутриигровых эмоций персонажа с привязками по умолчанию.\n• |cffffd100Сообщения чата:|r Отправка автоматических шаблонов сообщений в любой канал чата.\n• |cffffd100Игрушки и макросы:|r Создание сложных цепочек макросов, включая игрушки и экипировку, с анимированным предпросмотром разделенной иконки.\n• |cffffd100Action Hub:|r Настройка радиальных меню с мощной многоузловой логикой и позиционированием.\n• |cffffd100OxedRing:|r Круговые радиальные меню с настраиваемыми размерами узлов, продвинутыми назначениями (игрушки, эмоции, метки, предметы) и стилизованными фонами."
L["ABOUT_CARD_HOW"] = "Как использовать"
L["ABOUT_HOW_DESC"] = "|cffffd1001. Вкладка Actions:|r Начните здесь. Добавьте свои звуки, спрайт-листы анимаций и шаблоны чата.\n|cffffd1002. Вкладка Триггеры:|r Создайте правила с помощью кнопки Добавить новый Триггер (справа вверху). Выберите внутриигровое событие и назначьте действия.\n|cffffd1003. Вкладка Игрушки:|r Создавайте собственные макросы для игрушек с визуальным предпросмотром разделенной иконки и эффектами анимированного кольца.\n|cffffd1004. Action Hub:|r Настройте лимит узлов и квадрант. Назначьте любой макрос игрушки или реакцию. Свободно перетаскивайте в любое место на экране.\n|cffffd1005. OxedRing:|r Создавайте круговые радиальные меню с пользовательским количеством секторов, автоматическим сопоставлением эмоций с командами и стилизованными панелями назначения.\n|cffffd1006. Панель управления:|r Просматривайте все активные триггеры и переключайте профили с помощью выпадающего списка на главной карточке."
L["ABOUT_CARD_SETTINGS"] = "Настройки и профили"
L["ABOUT_SETTINGS_DESC"] = "• |cffffd100Профили:|r Создавайте несколько конфигураций для разных персонажей или стилей игры. Мгновенно переключайтесь из выпадающего списка на вкладке Dashboard.\n• |cffffd100Импорт/Экспорт:|r Используйте кнопку Экспорт, чтобы получить строку, которой можно поделиться с другими, или Импорт, чтобы добавить профиль друга в свой аддон."
L["ABOUT_CARD_TIPS"] = "Советы"
L["ABOUT_TIPS_DESC"] = "• |cffffd100Строка поиска:|r Вы можете искать по своим звукам, сообщениям чата и анимациям с помощью строки поиска.\n• |cffffd100Пользовательские файлы:|r При добавлении собственных звуков вы ОБЯЗАНЫ перезапустить клиент игры, чтобы World of Warcraft распознал новые файлы.\n• |cffffd100Настройки:|r Используйте вкладку Настройки для настройки основного звукового канала и управления данными профиля.\n• |cffffd100Назначения:|r Перетаскивайте эмоции, игрушки, метки или предметы прямо на узлы предпросмотра OxedRing для быстрого назначения."
L["ABOUT_CARD_UPDATES"] = "Недавние улучшения (v2.0.8)"
L["ABOUT_UPDATES_DESC"] = "• |cffffd100Улучшения интерфейса:|r Изменено положение элементов управления, оптимизировано размещение полосы прокрутки, обновлен стиль панели назначений с фоном Assignments.png.\n• |cffffd100Анимации:|r Добавлена анимация кругового кольца в микшер игрушек, удалены анимации при наведении в OxedRing для более чистого взаимодействия.\n• |cffffd100Эмоции по умолчанию:|r Встроенные эмодзи теперь автоматически связываются с соответствующими эмоциями (Angry→/angry, Kiss→/kiss и т. д.).\n• |cffffd100Надежность макросов:|r Исправлено выполнение микса игрушек после входа/выхода из игры благодаря предварительной загрузке данных по клику.\n• |cffffd100Исправления слоев:|r Исправлен уровень слоев фреймов для оверлея главного меню и панелей назначения, чтобы предотвратить конфликты интерфейса."
L["ABOUT_CARD_COMMUNITY"] = "Сообщество и авторы"
L["ABOUT_COMMUNITY_DESC"] = "Присоединяйтесь к нашему сообществу в Discord, чтобы делиться профилями, получать поддержку и предлагать новые функции."
L["ABOUT_BTN_DISCORD"] = "Войти в Discord"
L["ABOUT_THANKS"] = "Особая благодарность |cffa335eeCaritas|r, |cffa335eeRiyadh|r и |cffa335eeialaaeldin|r за предложения и тестирование!\nОсобая благодарность |cffa335eeRomanv|r за испанскую локализацию.\nОсобая благодарность |cffa335eeZamestoTV|r за русскую локализацию.\nЕсли вы хотите внести свой вклад в перевод, пожалуйста, свяжитесь с нами!"
L["ABOUT_CREATED_BY"] = "Создано Oxed и The Lav Forge."
L["ABOUT_DISCORD_LABEL"] = "|cff00ff00Сообщество Discord:|r Скопируйте ссылку ниже и вставьте ее в браузер"

