L["TIPS_GETTING_STARTED_TITLE"] = "Начало работы"
L["TIPS_GETTING_STARTED_DESC"] = "|cffc8c8c8Принцип работы триггера: выберите |cffffd100Тип события|r, задайте для него |cffffd100Условия|r, а затем выберите |cffffd100Действия|r. Когда событие происходит и условия совпадают, запускаются действия.|r\n|cff80c0ffПример:|r |cffc8c8c8Событие = Успешное заклинание, Условие = Камень возвращения, Действие = воспроизвести звук + /привет.|r"
L["TIPS_COMBAT_SPELLS_TITLE"] = "Бой и заклинания"
L["TIPS_COMBAT_SPELLS_DESC"] = "• |cffffd100Получение/потеря ауры:|r Вы получаете или теряете положительный/отрицательный эффект.\n   |cff80c0ffПример:|r Звук рога при срабатывании Героизма. Добавьте несколько заклинаний, чтобы это также работало для Жажды крови / Искажения времени.\n• |cffffd100Успешное заклинание:|r Вы завершаете применение заклинания.\n   |cff80c0ffПример:|r /глупость при каждом создании портала.\n• |cffffd100Восстановление завершено:|r Отслеживаемое заклинание восстанавливается.\n   |cff80c0ffПример:|r Чат Прерывание готово!, когда ваш сбивающий каст навык восстановился.\n• |cffffd100Прерывание:|r Вы используете свое прерывание (применение / успех / промах).\n• |cffffd100Заклинание прервано:|r Ваше собственное чтение заклинания сбивают."
L["TIPS_ENCOUNTERS_TITLE"] = "Сражения и группа"
L["TIPS_ENCOUNTERS_DESC"] = "• |cffffd100Начало боя с боссом:|r Начинается битва с боссом.\n   |cff80c0ffПример:|r Включение эпической музыки в момент пулла.\n• |cffffd100Конец боя с боссом:|r Битва завершается (победа или вайп).\n• |cffffd100Босс убит:|r Ваша группа побеждает босса.\n   |cff80c0ffПример:|r Эмоция победы + победный звук при убийстве.\n• |cffffd100М+ завершено:|r Подземелье в режиме эпохального ключа (Мифик+) пройдено.\n• |cffffd100Призыв:|r Появляется призыв (например, в подземелье), либо он принимается/отклоняется."
L["TIPS_CHARACTER_STATE_TITLE"] = "Состояние персонажа"
L["TIPS_CHARACTER_STATE_DESC"] = "• |cffffd100Игрок погиб:|r Ваш персонаж умирает.\n   |cff80c0ffПример:|r Драматичный звук «упс» при вашей смерти.\n• |cffffd100Потеря / восстановление контроля:|r Страх, подчинение разума, полет на такси и т. д.\n• |cffffd100Эффект еды/питья:|r Вы едите или пьете (Сытость).\n• |cffffd100Получено достижение:|r Вы зарабатываете достижение."
L["TIPS_PETS_TITLE"] = "Питомцы"
L["TIPS_PETS_DESC"] = "• |cffffd100Питомец погиб:|r Ваш питомец умирает.\n• |cffffd100Питомец призван:|r Вы призываете питомца.\n• |cffffd100Питомец отпущен:|r Вы отпускаете питомца."
L["TIPS_HANDY_TIPS_TITLE"] = "Полезные советы"
L["TIPS_HANDY_TIPS_DESC"] = "• |cffffd100Несколько заклинаний (Аура):|r В событии Получение/потеря ауры можно указать более одного заклинания - триггер сработает, если ЛЮБОЕ из них появится или исчезнет.\n• |cffffd100Все классы:|r Оставьте флажок включенным, чтобы реагировать на межклассовые эффекты (Героизм и т. д.).\n• |cffffd100Срабатывание на потерю / оба варианта:|r Выберите, когда запускать триггер: при получении ауры, ее потере или в обоих случаях.\n• |cffffd100Задержка эффектов:|r Задайте время восстановления в Параметрах, чтобы при спаме комбинации/триггера звуки не повторялись без остановки.\n• |cffffd100Кнопка проверки:|r Используйте её (вверху справа) для предпросмотра звука/анимации/эмоции триггера без необходимости дожидаться самого события."

