L["AH_GUIDE_HEARTHSTONES_TITLE"] = "Комбинация камней возвращения"
L["AH_GUIDE_HEARTHSTONES_DESC"] = "Совет: объедините все ваши игрушки-телепорты и камни возвращения в один слот. ActionHub автоматически выберет наилучший вариант в зависимости от времени их восстановления."
L["AH_GUIDE_ENGINEERING_TITLE"] = "Инженерные гаджеты"
