L["AH_GUIDE_MOUNTS_TITLE"] = "Умная смесь транспорта"
L["AH_GUIDE_MOUNTS_DESC"] = "Совет: призывайте любимый транспорт, не забивая панель команд. Создает умный слот, который предлагает летающий транспорт в зонах для полетов, наземный - в остальных местах или водный - при нахождении в воде."
L["AH_GUIDE_MACROS_TITLE"] = "Защищенные макросы"
L["AH_GUIDE_MACROS_DESC"] = "Совет: пишите сложные кастомные макросы, которые выполняют сразу несколько действий, не расходуя при этом лимит стандартных слотов для макросов Blizzard вашего персонажа."
L["AH_GUIDE_SELF_BUFF_TITLE"] = "Отслеживание собственных эффектов"
L["AH_GUIDE_SELF_BUFF_DESC"] = "Совет: привяжите сюда защитные эффекты (баффы) или настои. В сочетании с кастомным триггером ActionHub включит звуковое оповещение и подсветит их, когда время действия истечет."
L["AH_GUIDE_REACTION_TRIGGERS_TITLE"] = "Триггеры реакций"
L["AH_GUIDE_REACTION_TRIGGERS_DESC"] = "Совет: настройте триггеры для вывода звуковых оповещений и предупреждений, когда вы наносите смертельный удар, успешно прерываете заклинание или начинаете бой с боссом."
L["AH_GUIDE_KEYBINDS_TITLE"] = "Динамические клавиши"
