-- ============================================================================
-- Text keys. Here the English text itself is the key: code asks for
-- L["Show on screen"] and gets the English back when no line below matches.
-- ============================================================================
L["Thanks to everyone testing & sharing profiles."] = "Спасибо всем, кто тестирует и делится профилями."
L["Basic Triggers"] = "Базовые триггеры"
L["General events like mounts, leveling, mail, achievements, and party invites"] = "Общие события: маунты, новый уровень, почта, достижения и приглашения в группу"
L["Combat Triggers"] = "Боевые триггеры"
L["Combat events like interrupts, boss encounters, deaths, and cooldowns"] = "Боевые события: прерывания, боссы, смерти и восстановление способностей"
L["PvP Triggers"] = "PvP-триггеры"
L["Player versus Player kills, multi-kills, and sprees"] = "Убийства игроков, мультикиллы и серии убийств"
L["Advanced Triggers"] = "Продвинутые триггеры"
L["Configurable triggers requiring spell IDs, aura names, or proc glows"] = "Настраиваемые триггеры, которым нужны ID заклинаний, названия аур или подсветка проков"
L["Aura Gained/Lost"] = "Аура получена/потеряна"
L["When you gain or lose a buff/debuff"] = "Когда вы получаете или теряете бафф/дебафф"
L["My Buff (by Spell ID)"] = "Мой бафф (по ID заклинания)"
L["Detect one of YOUR buffs by spell ID (e.g. Power Infusion). Works out of combat now; sound also plays IN COMBAT on WoW 12.1+ (native aura sound)."] = "Отслеживает один из ВАШИХ баффов по ID заклинания (например, Придание сил). Работает вне боя; звук играет и В БОЮ в WoW 12.1+ (встроенный звук ауры)."
L["Spell Proc Glow (by Spell ID)"] = "Подсветка прока (по ID заклинания)"
L["Fires when a spell's proc/activation glow appears on your bar (e.g. Sudden Doom lighting up Death Coil). Uses the game's proc-glow event, so it works IN COMBAT."] = "Срабатывает, когда на панели загорается подсветка прока заклинания (например, Внезапная смерть подсвечивает Лик смерти). Использует игровое событие подсветки, поэтому работает В БОЮ."
L["Spell Cast Success"] = "Успешное применение"
L["When you successfully cast a spell (e.g., Sprint, Hearthstone, Portals)"] = "Когда вы успешно применяете заклинание (например, Спринт, Камень возвращения, порталы)"
L["Spell Cast Start"] = "Начало применения"
L["The moment you BEGIN casting, not when it lands -- use this to call something out while the cast bar is still running (e.g. Mass Resurrection). Only works for spells with a cast time or a channel; instants have no start to announce."] = "В момент, когда вы НАЧИНАЕТЕ применение, а не когда оно завершается. Подходит, чтобы объявить что-то, пока полоса заклинания ещё идёт (например, Массовое воскрешение). Работает только для заклинаний со временем применения или поддержания; у мгновенных нет начала."
L["Trinket Used (on-use)"] = "Использован аксессуар"
L["When you press one of your equipped trinkets. Pick a specific trinket, or leave it unpicked to react to either of them.\n\nOnly trinkets you click. A trinket that goes off by itself cannot be detected: it casts nothing, its cooldown is not readable, and this game version does not let an addon read your buffs at all -- so nothing reaches the addon to react to."] = "Когда вы нажимаете один из надетых аксессуаров. Выберите конкретный или оставьте пустым, чтобы реагировать на любой из двух.\n\nТолько аксессуары, которые вы нажимаете сами. Срабатывающий сам по себе аксессуар отследить нельзя: он ничего не применяет, его восстановление не читается, а эта версия игры вообще не даёт аддонам читать ваши баффы. Реагировать просто не на что."
L["Potion Used"] = "Использовано зелье"
L["When you drink a potion, flask or elixir. Pick a specific one from your bags, or leave it unpicked to react to any."] = "Когда вы выпиваете зелье, настой или эликсир. Выберите конкретное из сумок или оставьте пустым, чтобы реагировать на любое."
L["Disenchant Insight"] = "Анализ распыления"
L["Analyze and track Disenchant values vs vendor prices directly on tooltips"] = "Анализ и учёт стоимости распыления против цены у торговца прямо в подсказках"
L["Summon"] = "Призыв"
