L["Prey Hunt is now a module: Modules > Prey Hunt. Its bar, widget, gossip marks and sounds are set there."] = "Охота на добычу теперь модуль: Модули > Prey Hunt. Её полоса, виджет, метки в диалогах и звуки настраиваются там."
