L["An icon while a priest's Power Infusion is on you; the game draws it, so it works in combat (no sound)"] = "Значок, пока на вас Придание сил жреца. Его рисует сама игра, поэтому работает в бою (без звука)"
L["My Target Debuffs"] = "Мои дебаффы на цели"
