L["Smirk"] = "Ухмылка"
L["The instant a cast completes -- after the cast bar finishes, or immediately for an instant spell."] = "В момент завершения применения: после того как полоса заклинания заполнится, или сразу для мгновенного заклинания."
L["At least one spell chosen. Without one it would fire on everything you cast, so it stays silent."] = "Нужно выбрать хотя бы одно заклинание. Без него правило срабатывало бы на всё подряд, поэтому оно молчит."
L["Too late to warn anybody about a long cast: by the time this fires, the spell has already landed. Use Spell Cast Start for that."] = "Слишком поздно, чтобы предупредить о долгом заклинании: к моменту срабатывания оно уже применено. Для этого есть «Начало применения»."
L["Play a sound when you use Hearthstone, or when a portal goes down."] = "Проиграть звук, когда вы используете Камень возвращения или когда открывается портал."
L["The moment the cast bar appears, and again when a channel begins."] = "В момент появления полосы заклинания, а также когда начинается поддерживаемое заклинание."
L["At least one spell chosen, for the same reason as Spell Cast Success."] = "Нужно выбрать хотя бы одно заклинание, по той же причине, что и для «Успешного применения»."
L["Instant spells never reach this. They have no cast to begin, and the game sends nothing -- a rule built on one will simply never fire."] = "Мгновенные заклинания сюда не попадают. У них нет начала, и игра ничего не присылает, так что такое правило просто никогда не сработает."
L["Announce Mass Resurrection while it is still casting, so the raid knows to stop moving."] = "Объявить Массовое воскрешение, пока оно ещё применяется, чтобы рейд знал, что двигаться нельзя."
L["Whenever a buff or debuff on you changes -- gained, refreshed, or lost."] = "Каждый раз, когда бафф или дебафф на вас меняется: получен, обновлён или потерян."
L["A spell or aura name. This event is one of the busiest in the game."] = "Заклинание или название ауры. Это одно из самых частых событий в игре."
L["Fires for refreshes too, so a stacking aura can announce itself repeatedly. Sound is blocked mid-combat on some builds; My Buff (by Spell ID) uses the native path and is not."] = "Срабатывает и на обновления, поэтому накапливающаяся аура может объявлять себя снова и снова. На некоторых сборках звук в бою заблокирован; «Мой бафф (по ID заклинания)» использует встроенный путь и не блокируется."
L["React when you pick up a specific raid buff."] = "Отреагировать, когда вы получаете определённый рейдовый бафф."
L["When one of your own buffs, matched by spell ID, appears or disappears."] = "Когда один из ваших баффов, найденный по ID заклинания, появляется или исчезает."
L["The spell ID of the buff you want watched."] = "ID заклинания баффа, за которым нужно следить."
L["Yours only. It will not see anything on your target or on other players."] = "Только ваши. Ничего на цели или на других игроках он не видит."
L["A sound the moment Power Infusion lands on you."] = "Звук в момент, когда на вас накладывают Придание сил."
L["When a spell's proc glow lights up on your action bar."] = "Когда на панели команд загорается подсветка прока заклинания."
L["The spell whose glow you are watching."] = "Заклинание, подсветку которого вы отслеживаете."
L["Follows the bar, not the buff: a proc for a spell you have not placed on a bar has no glow to detect."] = "Следит за панелью, а не за баффом: у прока заклинания, которого нет на панели, нет подсветки."
L["Call out Sudden Doom lighting up Death Coil."] = "Объявить, что Внезапная смерть подсветила Лик смерти."
L["When a tracked spell finishes its cooldown."] = "Когда у отслеживаемого заклинания заканчивается восстановление."
L["The spell to track. Tracking is armed the first time you cast it."] = "Заклинание для отслеживания. Отслеживание начинается после первого применения."
L["Nothing happens until you have cast the spell at least once in this session, since that is what starts the timer."] = "Ничего не происходит, пока вы не примените заклинание хотя бы раз за сеанс, ведь именно это запускает таймер."
L["A cue when your interrupt is back up."] = "Сигнал, когда прерывание снова готово."
L["When you use an interrupt ability, whether or not it lands."] = "Когда вы используете прерывание, неважно, попало оно или нет."
L["Says you pressed it, not that it worked. Interrupt Success is the one that means a cast was actually stopped."] = "Говорит, что вы нажали, а не что сработало. Что заклинание действительно прервано, означает «Успешное прерывание»."
L["A short sound so you can hear your own kicks in a noisy fight."] = "Короткий звук, чтобы слышать свои прерывания в шумном бою."
L["When you land a killing blow on an enemy player."] = "Когда вы наносите смертельный удар вражескому игроку."
L["Instanced content hides unit identity from addons, so this cannot always tell a player apart from a raid mob. It defaults to battlegrounds only for that reason -- widen the zones at your own risk."] = "В подземельях игра скрывает от аддонов, кто есть кто, поэтому игрока не всегда можно отличить от рейдового моба. Поэтому по умолчанию только поля боя. Расширяйте зоны на свой страх и риск."
L["A kill sound in battlegrounds."] = "Звук убийства на полях боя."
L["Continuously while your health is under the threshold you set, speeding up as it drops."] = "Постоянно, пока здоровье ниже заданного порога, и всё быстрее по мере падения."
L["Health only. It knows nothing about incoming damage, so a burst that kills you outright gives no warning."] = "Только здоровье. О входящем уроне он ничего не знает, поэтому резкий урон, который убивает сразу, ничем не предупреждается."
L["A pulse that gets faster below 35% health."] = "Пульс, который ускоряется ниже 35% здоровья."
L["When a summon appears for you, and again when you accept or decline it."] = "Когда вам приходит призыв, и ещё раз, когда вы его принимаете или отклоняете."
L["Different sounds for the summon arriving and for accepting it."] = "Разные звуки на появление призыва и на его принятие."
L["When you gain Well Fed or a drink buff."] = "Когда вы получаете Сытость или бафф от питья."
L["The buff, not the act. Starting to eat and being interrupted produces nothing."] = "Бафф, а не действие. Если начать есть и прерваться, ничего не будет."
L["A quiet cue that your food actually took."] = "Тихий сигнал, что еда сработала."
L["When you mount, dismount, or shift into a travel form."] = "Когда вы садитесь на маунта, спешиваетесь или принимаете походный облик."
L["A sound for mounting up, and a different one for landing."] = "Один звук на посадку, другой на приземление."
L["When you enter or leave combat."] = "Когда вы вступаете в бой или выходите из него."
L["Leaving combat is delayed by the game's own out-of-combat timer, so the cue lands a few seconds after the fight really ended."] = "Выход из боя запаздывает из-за игрового таймера, поэтому сигнал прозвучит через несколько секунд после реального конца боя."
L["Music or a sound to mark a pull."] = "Музыка или звук на пулл."
L["When Bloodlust, Heroism, Time Warp or an equivalent lands on you."] = "Когда на вас действует Жажда крови, Героизм, Искажение времени или аналог."
L["A sound the moment lust goes out."] = "Звук в момент, когда прожали бл."
L["When you earn an achievement."] = "Когда вы получаете достижение."
L["A celebration animation on every achievement."] = "Праздничная анимация на каждое достижение."
L["On Prey Hunt stage changes, gossip markers, and hunt progress."] = "При смене этапа Охоты на добычу, метках в диалогах и прогрессе охоты."
L["Beta. It reads the game's own quest widget, so it can only report what that widget shows."] = "Бета. Читает игровой виджет задания, поэтому сообщает только то, что показывает этот виджет."
L["When somebody offers you a resurrection."] = "Когда вам предлагают воскрешение."
L["A sound so you notice the box during a wipe."] = "Звук, чтобы заметить окно воскрешения во время вайпа."
