L["On by default. The search includes common cross-class spells (Bloodlust, Heroism, Time Warp, Primal Rage, Power Infusion, etc.) so you can react to spells that aren't from your class."] = "Включено по умолчанию. Поиск включает общие заклинания других классов (Жажда крови, Героизм, Искажение времени, Исконная ярость, Придание сил и т. д.), чтобы можно было реагировать на заклинания не вашего класса."
