L["|cff00ff00Native Engine|r"] = "|cff00ff00Встроенный движок|r"
L["Plays a voice alert when your target, focus, or arena enemy uses a potion or consumable.\n\n"] = "Проигрывает голосовой сигнал, когда ваша цель, фокус или противник на арене использует зелье или расходник.\n\n"
L["Note: Icons and Animations are NOT supported for this trigger "] = "Примечание: значки и анимации для этого триггера НЕ поддерживаются "
L["due to Blizzard PvP restrictions. Only Sounds will play."] = "из-за ограничений Blizzard в PvP. Играют только звуки."
L["Automatically announces enemy buffs (defensives, offensives, utility) "] = "Автоматически объявляет баффы врагов (защитные, атакующие, вспомогательные) "
L["using the 12.1 AddAuraSound API. Tracks your target, focus, and arena "] = "через API AddAuraSound из 12.1. Следит за целью, фокусом и противниками "
L["enemies. The sound you pick in the 'Actions' tab below will play "] = "на арене. Звук, выбранный ниже на вкладке «Действия», прозвучит "
L["instantly when an enemy gains a tracked buff.\n\n"] = "сразу, как только враг получит отслеживаемый бафф.\n\n"
L["Plays an alert sound when a friendly healer in your party/raid is crowd "] = "Проигрывает сигнал, когда на дружественного лекаря в группе/рейде действует "
L["controlled. Uses the 12.1 AddAuraSound API to reliably track CC "] = "контроль. Использует API AddAuraSound из 12.1, чтобы надёжно отслеживать ауры "
L["auras across all healers in the group automatically.\n\n"] = "контроля на всех лекарях группы автоматически.\n\n"
L["Plays a voice alert when you get CC'd (stunned, feared, polymorphed, "] = "Проигрывает голосовой сигнал, когда на вас действует контроль (оглушение, страх, превращение, "
L["silenced, etc.). Uses the 12.1 AddAuraSound API for instant, "] = "немота и т. д.). Использует API AddAuraSound из 12.1 для мгновенного "
L["in-combat detection.\n\n"] = "обнаружения в бою.\n\n"
L["Plays a voice alert when your target, focus, or arena enemy uses their PvP trinket (Gladiator's Medallion or Adaptation).\n\n"] = "Проигрывает голосовой сигнал, когда ваша цель, фокус или противник на арене использует PvP-аксессуар (Медальон гладиатора или Адаптацию).\n\n"
L["Major Cooldowns"] = "Большие кулдауны"
L["Interrupts"] = "Прерывания"
L["Defensives"] = "Защитные"
L["Crowd Control"] = "Контроль"
L["Movement"] = "Передвижение"
L["Other Abilities"] = "Другие способности"
L["What do you wish to monitor?"] = "Что вы хотите отслеживать?"
L["Triggers act as your personal combat assistants. They allow you to attach custom audio cues, screen flashes, or on-screen icons to specific events in combat. This helps you react faster to important cooldowns, interrupts, or defensive buffs without having to constantly watch your action bars."] = "Триггеры — ваши личные помощники в бою. Они позволяют привязать к событиям в бою свои звуковые сигналы, вспышки на экране или значки. Так вы быстрее реагируете на важные кулдауны, прерывания и защитные баффы и не следите постоянно за панелями команд."
L["Track an Aura / Buff"] = "Отслеживать ауру / бафф"
L["Monitor how long a buff or aura is active on you.\n\nE.g. Defensive cooldown durations, burst windows, or procs."] = "Следить, сколько бафф или аура действует на вас.\n\nНапример, длительность защитных кулдаунов, окна бурста или проки."
L["Track a Spell Cast"] = "Отслеживать применение заклинания"
L["Trigger a specific sound, animation, or icon when you cast an ability (or mix with toys!).\n\nE.g. Audio alert when casting an interrupt or major cooldown."] = "Проиграть звук, анимацию или показать значок, когда вы применяете способность (можно вместе с игрушками!).\n\nНапример, звуковой сигнал при прерывании или большом кулдауне."
L["Tick the spells you want to track, then press Create. Only spells this character actually has are listed."] = "Отметьте заклинания для отслеживания и нажмите «Создать». В списке только заклинания, которые есть у этого персонажа."
