L["It does NOT detect normal buffs (like Power Infusion). Buffs need aura detection, which WoW blocks in combat — so there is no reliable in-combat trigger for them yet."] = "Обычные баффы (как Придание сил) НЕ обнаруживаются. Для баффов нужно отслеживание аур, а WoW блокирует его в бою, поэтому надёжного триггера на них в бою пока нет."
