L["|cff888888• Exports are compressed base64 strings safe for sharing.\n• Large configurations are automatically split into manageable parts.\n• Author metadata and notes are bundled with the export.|r"] = "|cff888888• Экспорт — это сжатые строки base64, ими безопасно делиться.\n• Большие конфигурации автоматически делятся на удобные части.\n• Автор и заметки сохраняются вместе с экспортом.|r"
L["Open Import Dialog"] = "Открыть окно импорта"
L["Paste any export string to preview and import triggers, profiles, or hubs."] = "Вставьте любую строку экспорта, чтобы посмотреть и импортировать триггеры, профили или хабы."
L["Smart Import Features:"] = "Умный импорт:"
L["• |cffffd100Auto-Scope Detection:|r Automatically detects full profiles, triggers, rings, or action hubs."] = "• |cffffd100Автоопределение:|r сам распознаёт полные профили, триггеры, кольца или хабы."
L["• |cffffd100Safe Confirmation:|r Previews authors, notes, and full content tables before applying."] = "• |cffffd100Безопасное подтверждение:|r показывает авторов, заметки и всё содержимое до применения."
L["• |cffffd100Non-Destructive:|r Partial imports merge safely into your active profile without data loss."] = "• |cffffd100Без потерь:|r частичный импорт аккуратно добавляется в активный профиль, ничего не теряя."
L["• |cffffd100Multi-Part Paste:|r Paste chunked multi-part strings in any order without confusion."] = "• |cffffd100Импорт по частям:|r вставляйте части строки в любом порядке."
L["Clear the import history for the active profile?\nThis only removes the credits list, not the imported content."] = "Очистить историю импорта для активного профиля?\nУдалится только список авторов, а не импортированное содержимое."
