-- Module cards: the desc each module passes to ModuleAPI:Register
L["A character window tab with live move speed and hidden stats like leech and stagger."] = "Вкладка в окне персонажа: скорость передвижения и скрытые характеристики вроде самоисцеления и пошатывания."
L["Deposits reagents and restocks what you already store when the bank opens."] = "При открытии банка кладёт реагенты и пополняет то, что вы уже там храните."
L["Types DELETE for you and skips the confirm popups you pick in Options."] = "Сам вводит DELETE и пропускает выбранные в настройках окна подтверждения."
L["Picks the option when an NPC's menu has only one. Choose where in Options."] = "Выбирает вариант, когда у НИП он один. Где именно, задаётся в настройках."
L["Accepts and hands in quests when you talk to NPCs. Choose what it does in Options."] = "Берёт и сдаёт задания при разговоре с НИП. Что именно, задаётся в настройках."
L["Answers role checks, signs up in Group Finder, movable LFG eye that lists your queues."] = "Отвечает на проверку ролей, записывает в поиск группы, глаз очереди со списком очередей."
L["Sells junk and your sell list, and repairs, at any vendor. Set it up in Options."] = "Продаёт хлам и ваш список на продажу и чинит у любого торговца. Настройка в опциях."
L["Asks before a bonus roll is spent, and names the spec the loot goes to."] = "Спрашивает перед тратой бонусного броска и называет специализацию для добычи."
L["Countdown and text alerts in the middle of the screen for boss abilities."] = "Отсчёт и текстовые оповещения о способностях босса в центре экрана."
L["A health bar per boss, marked where the fight changes phase."] = "Полоса здоровья для каждого босса с отметками смены фаз."
L["Bars for coming boss abilities, each with its own sound, text and timing."] = "Полосы будущих способностей босса, у каждой свой звук, текст и время."
L["Boss abilities as icons sliding toward a line, and big icon alerts as they land."] = "Способности босса значками, которые едут к линии, и большие значки, когда они срабатывают."
L["Cooldowns of dangerous dungeon trash after each pull, shown by the boss modules."] = "Восстановление опасных способностей мобов подземелья после пулла, в модулях боссов."
L["A friendly reminder to take a break after a long session. Never in a fight."] = "Дружеское напоминание отдохнуть после долгой игры. Никогда в бою."
L["Tracks Battle Resurrection charges and Sated debuffs on screen."] = "Показывает заряды боевого воскрешения и дебаффы Пресыщения на экране."
L["Chat bubbles with your font, size and look; off in dungeons or raids if you like. /oxbubble"] = "Облачка чата с вашим шрифтом, размером и видом; можно выключить в подземельях. /oxbubble"
L["Track any buff on you with a big icon and timer, also in a fight."] = "Любой бафф на вас большим значком с таймером, и в бою тоже."
L["Icons for missing buffs, pets and consumables. Click one to cast it."] = "Значки недостающих баффов, питомцев и расходников. Нажмите, чтобы применить."
L["Shift-click a vendor item to buy any amount: Stack, Max, and the total cost."] = "Shift+клик по товару, чтобы купить любое количество: стопка, максимум, общая цена."
L["ActionCam in a window: tilt, over the shoulder, target focus, zoom, field of view."] = "ActionCam в окне: наклон, вид из-за плеча, фокус на цели, зум, угол обзора."
L["Say, Group and Guild buttons by the chat: whisper history, quick lines, ready checks, guild alerts."] = "Кнопки «Сказать», «Группа» и «Гильдия» у чата: шёпоты, быстрые фразы, проверки готовности."
L["Unlimited ignore list, LFG warnings, Blizzard 50-slot sync, and spam blocking. /oxfilter"] = "Безлимитный игнор, предупреждения в поиске группы, синхронизация с Blizzard и антиспам. /oxfilter"
L["Right-click a channel in chat to leave it, no /leave needed."] = "ПКМ по каналу в чате, чтобы выйти из него, без /leave."
L["Needs a key: Key Bindings, OxedHub, Copy Chat. Opens the chat as text to copy."] = "Нужна клавиша: Назначение клавиш, OxedHub, Copy Chat. Открывает чат текстом для копирования."
L["Every currency for all your characters, with totals across them. /oxcurrency"] = "Все валюты всех ваших персонажей с общими суммами. /oxcurrency"
L["Adds a quick transfer button and quick browsing for account-wide currency transfers."] = "Кнопка быстрого перевода и быстрый просмотр для переводов валюты между персонажами."
L["Fire, frost, meteor and more on your pointer: halo, trail, click ripples."] = "Огонь, лёд, метеор и другое на курсоре: ореол, шлейф, круги от кликов."
L["Gear durability on screen, worst slots and repair cost, and reminders before a dungeon."] = "Прочность экипировки на экране, худшие ячейки, цена ремонта и напоминания перед подземельем."
L["A sleek experience bar with completed quest XP overlays, rested bonus, and leveling rate. /oxexp"] = "Полоса опыта с опытом готовых заданий, бонусом отдыха и скоростью прокачки. /oxexp"
L["Every enemy and boss cast in one list, with its target. Grey if it cannot be kicked."] = "Все заклинания врагов и боссов в одном списке с целью. Серые нельзя прервать."
L["Takes all the loot at once, the moment the window opens."] = "Забирает всю добычу сразу, как только открывается окно."
L["A timer bar on flight paths, with a sound before you land. Type /oxflight."] = "Полоса таймера в полёте и звук перед посадкой. Введите /oxflight."
L["Tracks gold world quests, special assignments, and weekly caches in Midnight."] = "Отслеживает задания за золото, особые поручения и еженедельные тайники в Midnight."
L["Dynamic heartbeat sound effects: steady pulse in combat, fast danger pulse at 35% HP, and death flatline."] = "Звук сердцебиения: ровный пульс в бою, частый при 35% здоровья и остановка сердца при смерти."
L["Counts your instances an hour and logs what each run was worth. /oxinst"] = "Считает подземелья за час и записывает, сколько принёс каждый заход. /oxinst"
L["Class, realm, and whether you know them, under every group invite."] = "Класс, сервер и знакомы ли вы, под каждым приглашением в группу."
L["Adds ID numbers, aura info, collection status and counts across your alts on hover."] = "При наведении: ID, данные аур, статус коллекции и количество у ваших альтов."
L["Interrupt alert icon on enemy nameplates or floating HUD with timer, proc glow, and almost-ready preview."] = "Значок прерывания над врагом или на экране: таймер, подсветка и «почти готово»."
L["Trims the boss loot banner: none solo, only good items, or only yours."] = "Урезает баннер добычи с босса: без него соло, только хорошее или только ваше."
L["Open All, return, forward, an address book and bag attaching. Type /oxmail."] = "Открыть всё, вернуть, переслать, адресная книга и вложение из сумок. Введите /oxmail."
L["Raid marks, world flares, ready check and a pull timer on screen. Type /oxmark."] = "Рейдовые метки, сигнальные огни, проверка готовности и таймер пулла. Введите /oxmark."
L["Scans chat, NPC dialogue and spells for keywords to trigger physical screen effects and sounds."] = "Ищет ключевые слова в чате, речи НИП и заклинаниях и запускает эффекты на экране и звуки."
L["Every addon's minimap button gathered behind one button, in a drawer. /oxmb"] = "Кнопки всех аддонов у миникарты собраны за одной кнопкой в выдвижном ящике. /oxmb"
L["Marks gear with empty gem sockets and reminds you before a dungeon or raid."] = "Отмечает экипировку с пустыми гнёздами и напоминает перед подземельем или рейдом."
L["Mythic+ & raid loot browser with a Best-in-Slot planner, drop reminders and keystone tooltips."] = "Добыча М+ и рейдов: планировщик BiS, напоминания о дропе и подсказки ключей."
L["Your kick's cooldown, and who in your group just interrupted what."] = "Восстановление вашего прерывания и кто в группе что прервал."
L["Hunt bar with stages, ambush and kill sounds, and achievement marks at Astalor."] = "Полоса охоты с этапами, звуки засады и убийства, метки достижений у Асталора."
L["Locks Yes for a moment on purchases you cannot undo, and says why."] = "Ненадолго блокирует «Да» при покупках, которые нельзя отменить, и объясняет почему."
L["Honour, conquest, vault wins and every rating on one panel. Type /oxpvp."] = "Честь, завоевание, победы для хранилища и все рейтинги на одной панели. Введите /oxpvp."
L["Names the quest an item starts before you delete it, and if you did it."] = "Перед удалением называет задание, которое начинает предмет, и выполнено ли оно."
L["Every reputation and renown for all your characters, with paragon alerts. /oxrep"] = "Вся репутация и известность всех ваших персонажей, с оповещениями о парагоне. /oxrep"
L["Smart auto-targeting for Misdirection (Hunter) and Tricks of the Trade (Rogue) with a 1-click secure macro."] = "Автовыбор цели для Перенаправления (охотник) и Маленьких хитростей (разбойник) в один клик."
L["A button your teleports fly out of, each group its own way. /tp"] = "Кнопка, из которой вылетают ваши телепорты, каждая группа по-своему. /tp"
L["A threat bar under every enemy nameplate, with a glow as you close in. /oxthreat"] = "Полоса угрозы под каждым врагом и подсветка, когда вы близко к агро. /oxthreat"
L["World quests up now that count toward achievements, mounts, pets or toys you still need."] = "Активные локальные задания, которые нужны для достижений, маунтов, питомцев или игрушек."

-- ============================================================================
-- Modules (Modules\OxedModules). Options windows translate their own text,
-- so most of these are only ever looked up by ModuleAPI.
-- ============================================================================
L["Each extra point of rating is worth %d%% of full value."] = "Каждое следующее очко рейтинга стоит %d%% полной ценности."
L["Lost to diminishing returns: %.2f%%"] = "Потеряно из-за убывающей отдачи: %.2f%%"
L["Worth less again after about %d more rating."] = "Ещё примерно через %d рейтинга ценность снова упадёт."
L[" |cff808080(skyriding)|r"] = " |cff808080(высший пилотаж)|r"
L[" |cff808080(vehicle)|r"] = " |cff808080(транспорт)|r"
L["Movement Speed"] = "Скорость передвижения"
L["Current: %.1f yards per second.\nStanding still reads 0%%."] = "Сейчас: %.1f м/с.\nСтоя на месте: 0%%."
L["Run / Swim / Fly"] = "Бег / плавание / полёт"
L["What you move at on foot, in water and on a flying mount, as a share of normal run speed. Skyriding shows live on the line above while you glide."] = "Скорость пешком, в воде и на летающем маунте в процентах от обычного бега. Высший пилотаж показывается вживую строкой выше, пока вы летите."
L["Speed"] = "Скорость"
L["Passive movement speed from the Speed secondary stat, on top of your normal run speed."] = "Пассивная скорость передвижения от вторичной характеристики «Скорость» сверх обычной скорости бега."
L["Leech"] = "Самоисцеление"
L["Part of the damage and healing you do comes back to you as healing."] = "Часть нанесённого урона и исцеления возвращается к вам исцелением."
L["Avoidance"] = "Избегание"
L["Reduces the damage area effects do to you."] = "Снижает урон, который вам наносят эффекты по области."
L["Critical Strike"] = "Критический удар"
L["Haste"] = "Скорость"
L["Mastery"] = "Искусность"
L["Versatility"] = "Универсальность"
L["Set a target for this stat in the module's Options and this bar fills toward it, with the rating you still need.\n\nUntil then the bars are drawn against your highest secondary, so you can see which is behind."] = "Задайте цель для этой характеристики в настройках модуля, и полоса будет заполняться к ней, показывая, сколько рейтинга ещё нужно.\n\nДо тех пор полосы рисуются относительно вашей самой высокой вторичной характеристики, чтобы было видно, какая отстаёт."
L["You are %.2f%% over the target you set (%s)."] = "Вы выше заданной цели на %.2f%% (%s)."
L["%s  |cffff9933+%d rating|r"] = "%s  |cffff9933+%d рейтинга|r"
L["%.2f%% short of your %s target.\nThat is about %d more rating, worked out from what the game says each amount is worth, so diminishing returns are already counted."] = "Не хватает %.2f%% до цели %s.\nЭто примерно ещё %d рейтинга, по данным игры о ценности каждого очка, так что убывающая отдача уже учтена."
L["%.2f%% short of your %s target."] = "Не хватает %.2f%% до цели %s."
L["Attribute"] = "Характеристика"
L["Base: %d\nFrom gear and effects: %+d"] = "Базовое: %d\nОт экипировки и эффектов: %+d"
L["Health: %d"] = "Здоровье: %d"
L["Melee: %s\nRanged: %s\nSpell: %s"] = "Ближний бой: %s\nДальний бой: %s\nЗаклинания: %s"
L["Diminishing returns below are in mastery points, before your spec turns them into this percentage."] = "Убывающая отдача ниже указана в очках искусности, до того как специализация переведёт их в этот процент."
L["Damage done: %s\nDamage taken: %s"] = "Наносимый урон: %s\nПолучаемый урон: %s"
L["Dodge"] = "Уклонение"
L["Parry"] = "Парирование"
L["A blocked hit is reduced by %d."] = "Заблокированный удар уменьшается на %d."
L["Block"] = "Блок"
L["Against your current target: %s"] = "Против текущей цели: %s"
L["Stagger"] = "Пошатывание"
L["Armor"] = "Броня"
L["Damage reduction"] = "Снижение урона"
L["Global cooldown"] = "Глобальное восстановление"
L["Fixed at one second for your class or form: haste does not shorten it."] = "Для вашего класса или облика всегда одна секунда: скорость её не сокращает."
L["1.5 s reduced by %s haste, never below 0.75 s."] = "1,5 с минус %s скорости, но не меньше 0,75 с."
L["Effective health"] = "Эффективное здоровье"
L["Physical / magic. Your %s health, after armour (%s) and versatility (%s) take their share of each hit."] = "Физический / магический урон. Ваши %s здоровья после того, как броня (%s) и универсальность (%s) снимут свою долю с каждого удара."
