L["Remembers your stats as they are now. Change gear or talents afterwards and every line shows what went up in green and what went down in red."] = "Запоминает ваши характеристики как есть сейчас. Смените экипировку или таланты, и каждая строка покажет, что выросло (зелёным), а что упало (красным)."
L["Right-click to pick stats"] = "ПКМ, чтобы выбрать характеристики"
L["Stats on screen"] = "Характеристики на экране"
L["Target bars (this spec)"] = "Полосы целей (эта специализация)"
