L["Hide display"] = "Скрыть окно"
L["|cff00ccffOxedHub|r Stats display hidden. Bring it back with /oxstats."] = "|cff00ccffOxedHub|r Окно характеристик скрыто. Вернуть: /oxstats."
L["|cff00ccffOxedHub|r Switch the Attributes module on first (Modules page)."] = "|cff00ccffOxedHub|r Сначала включите модуль Attributes (страница Модулей)."
L["%s: |cff808080none|r"] = "%s: |cff808080нет|r"
L["Show stats on screen"] = "Показывать характеристики на экране"
L["A small box you can put anywhere. Drag it with the left button, right-click it to choose the stats and set your targets."] = "Небольшое окно, которое можно поставить куда угодно. Двигайте его левой кнопкой, ПКМ, чтобы выбрать характеристики и задать цели."
L["Right-click the box to pick what it shows. /oxstats toggles it."] = "ПКМ по окну, чтобы выбрать, что в нём показывать. /oxstats показывает и скрывает его."
L["Box background"] = "Фон окна"
L["Your specialisation's main stat and stamina."] = "Основная характеристика и выносливость вашей специализации."
L["Item level, and the equipped slot furthest behind."] = "Уровень предметов и самая отстающая надетая ячейка."
L["Diminishing returns"] = "Убывающая отдача"
L["Colours a rating orange once each extra point is worth less, and says how much is lost and when the next drop comes. The game itself is asked, so it follows every patch."] = "Окрашивает рейтинг в оранжевый, когда каждое очко стоит меньше, и пишет, сколько теряется и когда следующий спад. Данные берутся у самой игры, так что работают в любом патче."
L["Changes since snapshot"] = "Изменения с момента снимка"
L["After Save snapshot on the tab, every line shows how far it has moved: green up, red down."] = "После «Сохранить снимок» на вкладке каждая строка показывает изменение: зелёным вверх, красным вниз."
L["A live reading of how fast you are moving, plus the Speed stat."] = "Текущая скорость передвижения и характеристика «Скорость»."
L["Crit, haste, mastery and versatility, each with its rating, and your global cooldown."] = "Крит, скорость, искусность и универсальность с рейтингом, и ваше глобальное восстановление."
L["Leech and avoidance, the ones the sheet never prints."] = "Самоисцеление и избегание, которых нет в окне персонажа."
L["Armour and what it actually takes off a hit, dodge, parry, block, stagger."] = "Броня и сколько она реально снимает с удара, уклонение, парирование, блок, пошатывание."
L["Show ratings"] = "Показывать рейтинг"
L["Print the rating in grey next to each percentage."] = "Писать рейтинг серым рядом с каждым процентом."
L["Read vehicle speed"] = "Скорость транспорта"
L["While you are driving something, show its speed instead of your own."] = "Пока вы чем-то управляете, показывать его скорость вместо вашей."
L["A bar per secondary stat showing how far you are from a target you set, and how much more rating it would take."] = "Полоса для каждой вторичной характеристики: насколько вы далеки от заданной цели и сколько ещё нужно рейтинга."
L["Targets for the specialisation you are playing now. Zero means no target. The missing rating is worked out from what the game says each amount is worth, so diminishing returns are already counted."] = "Цели для специализации, которой вы играете сейчас. Ноль означает без цели. Недостающий рейтинг считается по данным игры о ценности каждого очка, так что убывающая отдача уже учтена."
L["Everything appears on the Attributes tab of your character window."] = "Всё показывается на вкладке «Характеристики» в окне персонажа."
L["Deposit %d reagent stack(s):"] = "Положить %d стопок реагентов:"
L["Put away %d stack(s) you already store:"] = "Убрать %d стопок того, что вы уже храните:"
L["\n\nGo ahead?"] = "\n\nПродолжить?"
L["|cffff5555the bank is full|r, nothing was put away."] = "|cffff5555банк заполнен|r, ничего не убрано."
L["deposited %d reagent stack(s)."] = "положено стопок реагентов: %d."
L["deposited %d reagent stack(s)"] = "положено стопок реагентов: %d"
L["put away %d stack(s)"] = "убрано стопок: %d"
L["|cffff5555bank filled up|r"] = "|cffff5555банк заполнился|r"
L["Deposit reagents"] = "Класть реагенты"
L["The same as pressing the game's own deposit button when the bank opens."] = "То же, что нажать игровую кнопку «Положить реагенты» при открытии банка."
L["Restock what you already store"] = "Пополнять то, что вы уже храните"
L["Sends anything from your bags that you already keep in the bank."] = "Отправляет из сумок всё, что у вас уже лежит в банке."
L["Send all trade goods"] = "Отправлять все хозяйственные товары"
L["Every trade good, whether or not you already store it. Off by default: it will send things you were carrying on purpose."] = "Все хозяйственные товары, хранятся они уже или нет. По умолчанию выключено: отправит и то, что вы носили с собой нарочно."
L["Say what was done in chat"] = "Сообщать в чат, что сделано"
L["One line after each visit saying how much was put away."] = "Одна строка после каждого визита, сколько убрано."
L["Ask before doing it"] = "Спрашивать перед действием"
L["Shows what is about to be deposited and waits for Yes. No leaves your bags as they are."] = "Показывает, что будет положено, и ждёт «Да». «Нет» оставляет сумки как есть."
L["Hold Shift to skip a visit"] = "Shift, чтобы пропустить визит"
L["With this on, holding Shift while opening the bank leaves your bags as they are for that visit."] = "Если включено, зажатый Shift при открытии банка оставляет сумки как есть на этот раз."
L["|cffffd100Deleting|r"] = "|cffffd100Удаление|r"
L["Type the delete word for you"] = "Вводить слово для удаления за вас"
L["Fills in the word the game asks for before destroying a good item."] = "Вписывает слово, которое игра просит перед уничтожением хорошего предмета."
L["Also for quest items"] = "Также для предметов заданий"
L["Destroying a quest item also abandons its quest."] = "Уничтожение предмета задания также отменяет задание."
L["Also for housing decor"] = "Также для украшений дома"
L["Destroying decor from your housing storage."] = "Уничтожение украшений из хранилища дома."
L["Press Accept too (no delete popup)"] = "Сразу нажимать «Принять» (без окна удаления)"
L["Deletes go through the moment you drop the item, with no chance to change your mind."] = "Удаление происходит сразу, как только вы бросаете предмет, без шанса передумать."
L["Hold Shift to see a popup anyway"] = "Shift, чтобы всё же увидеть окно"
L["With this on, holding Shift while doing the action shows its popup, whatever is ticked below."] = "Если включено, зажатый Shift при действии показывает его окно, что бы ни было отмечено ниже."
L["|cffffd100Skip these confirmations|r"] = "|cffffd100Пропускать эти подтверждения|r"
L["Selling an item you could still trade"] = "Продажа предмета, который ещё можно передать"
L["Loot from a group that can be traded for two hours. Selling it ends that."] = "Добыча из группы, которую можно передавать два часа. Продажа это прекращает."
L["Buying with currency or tokens"] = "Покупка за валюту или жетоны"
L["Purchases paid in currency, and ones that cannot be refunded."] = "Покупки за валюту и те, что нельзя вернуть."
L["Expensive purchases  |cffff5555(spends gold)|r"] = "Дорогие покупки  |cffff5555(тратит золото)|r"
L["The warning before buying something costly from a vendor."] = "Предупреждение перед покупкой чего-то дорогого у торговца."
L["Equipping or using a bind-on-equip item"] = "Надевание или использование предмета, становящегося персональным при надевании"
L["The item becomes soulbound, as it would if you pressed Accept."] = "Предмет станет персональным, как если бы вы нажали «Принять»."
L["Looting or rolling on a bind-on-pickup item"] = "Добыча или розыгрыш предмета, становящегося персональным при получении"
L["Replacing or binding an enchant"] = "Замена или привязка чар"
L["Trade warnings"] = "Предупреждения при обмене"
L["Enchanting an item in the trade window that would bind it, or lose its appearance."] = "Наложение чар на предмет в окне обмена, которое сделает его персональным или сотрёт его облик."
L["Mailing a non-refundable item"] = "Отправка почтой предмета без возврата"
L["Buying bank slots or tabs  |cffff5555(spends gold)|r"] = "Покупка ячеек или вкладок банка  |cffff5555(тратит золото)|r"
L["Abandoning a quest"] = "Отказ от задания"
L["Missing a popup? Type /oxconfirm after it appears to see its name."] = "Не хватает какого-то окна? Введите /oxconfirm после его появления, чтобы узнать его название."
L["no other confirmation popups have appeared this session."] = "других окон подтверждения в этом сеансе не появлялось."
L["popups seen this session that Auto Confirm does not handle:"] = "окна в этом сеансе, которые Auto Confirm не обрабатывает:"
L["chose |cffffd100%s|r."] = "выбрано |cffffd100%s|r."
L["Also in dungeons, raids and delves"] = "Также в подземельях, рейдах и вылазках"
L["Off, menus inside instances are always left for you to read."] = "Если выключено, меню внутри подземелий всегда остаются вам на прочтение."
L["Dungeon helpers: buffs, cauldron, prisoners"] = "Помощники в подземельях: баффы, котёл, пленники"
L["In this season's dungeons, the helper option is chosen even when the NPC offers others."] = "В подземельях этого сезона вариант помощника выбирается, даже если у НИП есть другие."
L["Say what was chosen in chat"] = "Сообщать в чат, что выбрано"
L["Hold Shift to read a menu yourself"] = "Shift, чтобы читать меню самому"
L["With this on, holding Shift while talking to an NPC leaves the menu to you."] = "Если включено, зажатый Shift при разговоре с НИП оставляет меню вам."
L["Only menus with a single option are chosen, never setting your hearthstone, and never when the NPC also has quests."] = "Выбираются только меню с одним вариантом, никогда не привязка камня возвращения и никогда, если у НИП есть ещё задания."
L["handed in"] = "сдано"
L["|cff40ff40+%d ilvl|r"] = "|cff40ff40+%d ур.|r"
L["|cffffd100Most gold|r"] = "|cffffd100Дороже всего|r"
L["Accept quests"] = "Брать задания"
L["Quests an NPC offers are accepted when you talk to them."] = "Задания, которые предлагает НИП, принимаются при разговоре с ним."
L["Hand in finished quests"] = "Сдавать выполненные задания"
L["Completed quests are handed in, and a single reward is taken. Quests that cost gold to hand in are left for you."] = "Выполненные задания сдаются, единственная награда забирается. Задания, сдача которых стоит золота, остаются вам."
L["Open quests from the NPC's menu"] = "Открывать задания из меню НИП"
L["Picks quests out of an NPC's conversation list instead of waiting for you to click them."] = "Выбирает задания из списка в диалоге НИП, не дожидаясь вашего щелчка."
L["Skip low-level quests"] = "Пропускать низкоуровневые задания"
L["Grey quests, far below your level, are left alone."] = "Серые задания, сильно ниже вашего уровня, не трогаются."
L["Include daily and repeatable quests"] = "Включая ежедневные и повторяемые задания"
L["Pick the reward worth the most gold"] = "Брать самую дорогую награду"
L["When a quest offers a choice, take the one that sells for most. Off, the choice is always yours."] = "Когда задание предлагает выбор, брать ту, что дороже продаётся. Если выключено, выбор всегда ваш."
L["Mark the reward worth the most gold"] = "Отмечать самую дорогую награду"
L["A gold coin and \"Most gold\" on that reward when the choice is yours."] = "Золотая монета и «Дороже всего» на этой награде, когда выбор за вами."
L["Mark rewards with a higher item level"] = "Отмечать награды с более высоким уровнем"
L["A green arrow and +N ilvl on rewards better than what you wear in that slot. Only items you can use, and armour of your class's type."] = "Зелёная стрелка и +N ур. на наградах лучше надетого в эту ячейку. Только предметы, которые вы можете использовать, и броня вашего типа."
