L["Clear log"] = "Очистить журнал"
L["Click any blocked row to ignore the sender. History is session-only."] = "Нажмите на любую заблокированную строку, чтобы игнорировать отправителя. История только за этот сеанс."
L["Chat Filter & Global Ignore"] = "Фильтр чата и общий игнор"
L["Search..."] = "Поиск..."
L["switched off. Switch it on in OxedHub's Modules page first."] = "выключен. Сначала включите его на странице Модулей OxedHub."
L["usage: /oxignore Name-Realm [note]"] = "использование: /oxignore Имя-Сервер [заметка]"
L["Never filter guild"] = "Не фильтровать гильдию"
L["Guild and officer chat, and guild members anywhere, are never hidden by filters."] = "Чат гильдии и офицеров, а также члены гильдии где угодно, никогда не скрываются фильтрами."
L["Never filter your group"] = "Не фильтровать свою группу"
L["Party, raid and instance chat are never hidden by filters."] = "Чат группы, рейда и подземелья никогда не скрывается фильтрами."
L["Never filter friends"] = "Не фильтровать друзей"
L["Friends and Battle.net friends are never hidden by filters."] = "Друзья и друзья Battle.net никогда не скрываются фильтрами."
L["Never word-filter whispers"] = "Не фильтровать шёпоты по словам"
L["Whispers skip the word filters and presets. Ignored players are still hidden."] = "Шёпоты пропускают фильтры слов и пресеты. Игнорируемые игроки всё равно скрыты."
L["Decline duels from ignored players"] = "Отклонять дуэли от игнорируемых"
L["Decline group invites from ignored players"] = "Отклонять приглашения в группу от игнорируемых"
L["Decline guild invites from ignored players"] = "Отклонять приглашения в гильдию от игнорируемых"
L["Decline trade requests from ignored players"] = "Отклонять обмен от игнорируемых"
L["Warn when an ignored player joins your group"] = "Предупреждать, когда игнорируемый вступает в вашу группу"
L["Warn when an ignored player whispers or talks in your group"] = "Предупреждать, когда игнорируемый шепчет или пишет в группе"
L["One line with your reason, at most every two minutes per player."] = "Одна строка с вашей причиной, не чаще раза в две минуты на игрока."
L["Warn about ignored players in the Group Finder"] = "Предупреждать об игнорируемых в поиске группы"
L["When you sign up to a group an ignored player leads, are invited by one, or one applies to your group."] = "Когда вы записываетесь в группу игнорируемого лидера, он вас приглашает или подаёт заявку в вашу группу."
L["Ask for a reason when ignoring"] = "Спрашивать причину при игнорировании"
L["A small window after each ignore, including the game's own Ignore. Skip keeps them ignored with no note."] = "Маленькое окно после каждого игнорирования, включая игровое. «Пропустить» оставляет игнор без заметки."
L["Remember who I played with"] = "Запоминать, с кем я играл"
L["Group, dungeon, key, raid, battleground and arena players, in the manager's Recent Players tab."] = "Игроки группы, подземелья, ключа, рейда, поля боя и арены, во вкладке «Недавние» менеджера."
L["Keep them for"] = "Хранить их"
L["Highlight ignored leaders in LFG / Group Finder"] = "Выделять игнорируемых лидеров в поиске группы"
L["Colors ignored group leaders red in M+ and Raid Finder, and displays your note in the tooltip."] = "Красит игнорируемых лидеров групп красным в М+ и поиске рейдов и показывает вашу заметку в подсказке."
L["Sync top 50 to Blizzard ignore list"] = "Синхронизировать 50 последних с игнор-листом Blizzard"
L["Keeps the 50 most recent ignores in Blizzard's native list for engine-level whisper and queue blocking."] = "Держит 50 последних игнорирований в родном списке Blizzard, чтобы игра сама блокировала шёпоты и очереди."
L["Ignored players are always hidden. The ignore list, word filters, built-in spam filters and the blocked log are in the manager."] = "Игнорируемые игроки всегда скрыты. Игнор-лист, фильтры слов, встроенные спам-фильтры и журнал блокировок находятся в менеджере."
L["Open manager"] = "Открыть менеджер"
L["|cffff6060Leave this channel|r"] = "|cffff6060Покинуть канал|r"
L["Right-click a channel's name in chat to find Leave this channel in the menu."] = "ПКМ по названию канала в чате, и в меню будет «Покинуть канал»."
L["One line"] = "Одна строка"
L["Click a line to select it, then Ctrl+C. Escape closes."] = "Нажмите на строку, чтобы выделить, затем Ctrl+C. Escape закрывает."
L["This chat window (%s) holds no messages."] = "В этом окне чата (%s) нет сообщений."
L["Unlocked: drag to move. Lock it again in Options."] = "Разблокировано: перетащите. Закрепить снова можно в настройках."
L["Copy %s"] = "Копировать %s"
L["%d line(s) in this window."] = "Строк в этом окне: %d."
L["Copy this chat window"] = "Скопировать это окно чата"
L["Opens Chattynator's copy window for it."] = "Открывает окно копирования Chattynator для него."
L["|cffff5555OxedHub:|r no chat window found."] = "|cffff5555OxedHub:|r окно чата не найдено."
L["Copy this window"] = "Скопировать это окно"
L["Button on each chat window"] = "Кнопка на каждом окне чата"
L["A small button in the corner of each chat window. Without it, use the right-click menu on a chat tab."] = "Маленькая кнопка в углу каждого окна чата. Без неё используйте меню по ПКМ на вкладке чата."
L["Unlock the button to move it"] = "Разблокировать кнопку для перемещения"
L["While ticked, drag the button with the mouse to anywhere on the chat window. Untick to lock it in place."] = "Пока отмечено, тащите кнопку мышью куда угодно в окне чата. Снимите, чтобы закрепить."
L["Reset position"] = "Сбросить позицию"
L["Plain text"] = "Простой текст"
L["Remove colour codes and link markup from the copy, keeping the words inside a link."] = "Убирать коды цвета и разметку ссылок из копии, оставляя слова внутри ссылки."
L["Keep timestamps"] = "Сохранять время"
L["Leave the time at the start of each line in the copy."] = "Оставлять время в начале каждой строки копии."
L["Keep /chatlog on"] = "Держать /chatlog включённым"
L["Turns the game's chat log file back on at login. The file is Logs/WoWChatLog.txt."] = "Снова включает файл журнала чата при входе. Файл: Logs/WoWChatLog.txt."
L["Set the key first: Escape, Options, Key Bindings, OxedHub, Copy Chat. Without a key, use /copychat or the button on the chat window.\n\nIn the window, click a line to select it and press Ctrl+C. Select all takes the whole log."] = "Сначала назначьте клавишу: Escape, Настройки, Назначение клавиш, OxedHub, Copy Chat. Без клавиши используйте /copychat или кнопку в окне чата.\n\nВ окне нажмите на строку, чтобы выделить, и нажмите Ctrl+C. «Выделить всё» берёт весь журнал."
