L["The first flight on a route is timed and written down. Every flight after that counts down from what was learned, and each new flight nudges the figure, so it settles on your own connection rather than on a table shipped with the addon."] = "Первый полёт по маршруту засекается и записывается. Каждый следующий отсчитывает от выученного, и каждый новый полёт немного поправляет цифру, так что она подстраивается под ваше соединение, а не под таблицу из аддона."
L["The landing sound is picked from your own OxedHub sounds, the same library the triggers use, and it plays through OxedHub so it follows your sound channel."] = "Звук посадки выбирается из ваших звуков OxedHub, той же библиотеки, что у триггеров, и играет через OxedHub, следуя вашему звуковому каналу."
