L["No names yet"] = "Имён пока нет"
L["Add the To name"] = "Добавить имя из «Кому»"
L["write a name on the send page first."] = "сначала впишите имя на странице отправки."
L["Copy to all"] = "Копия всем"
L["no other names to copy to."] = "больше некому отправлять копии."
L["write the letter first; copies carry its text, never its attachments."] = "сначала напишите письмо; копии несут его текст, но не вложения."
L["sending %d copies, one a second."] = "отправляем копий: %d, по одной в секунду."
L["Pick this letter"] = "Выбрать это письмо"
L["Then use Return or Tidy up on the bar below."] = "Затем используйте «Вернуть» или «Прибраться» на панели ниже."
L["no letters picked."] = "письма не выбраны."
L["%s %d letters."] = "%s писем: %d."
L["tick the letters to send back first."] = "сначала отметьте письма для возврата."
L["Send %d letters back to their senders?"] = "Вернуть отправителям писем: %d?"
L["sending back"] = "возвращаем"
L["nothing to tidy: every letter still holds something."] = "прибираться нечего: в каждом письме что-то есть."
L["Throw away %d read letters that hold nothing?"] = "Выбросить пустых прочитанных писем: %d?"
L["throwing away"] = "выбрасываем"
L["the letter is full: twelve attachments is the limit."] = "письмо заполнено: вложений не больше двенадцати."
L["Attach from bags"] = "Вложить из сумок"
L["Click an item to attach it. Twelve fit on a letter."] = "Нажмите на предмет, чтобы вложить. В письмо помещается двенадцать."
L["open a letter first."] = "сначала откройте письмо."
L["Forwarded mail"] = "Пересланное письмо"
L["ready to forward to |cffffd100%s|r%s. Press Send when it looks right."] = "готово к пересылке |cffffd100%s|r%s. Нажмите «Отправить», когда всё в порядке."
L[" with %d attachments"] = " с вложениями: %d"
L["not enough room in the bags to hold the attachments on the way."] = "в сумках не хватит места для вложений на время пересылки."
L["Forward this letter to:"] = "Переслать это письмо:"
L["Collect All"] = "Забрать всё"
L["Takes the attachments and the coins, one letter at a time, and stops when the bags fill rather than leaving half a letter behind. Cash on delivery letters are walked past. Press again to stop."] = "Забирает вложения и монеты по одному письму и останавливается, когда сумки заполняются, а не оставляет полписьма. Письма с наложенным платежом пропускаются. Нажмите снова, чтобы остановить."
L["Gold only"] = "Только золото"
L["Takes the coins and leaves every attachment where it is, for when the bags are full."] = "Забирает монеты и оставляет все вложения на месте, если сумки полны."
L["no coins waiting."] = "монет нет."
L["taking %s from %d letters."] = "забираем %s из писем: %d."
L["The names you write to. Click one to start a letter, right-click to forget it."] = "Имена, которым вы пишете. Нажмите, чтобы начать письмо, ПКМ, чтобы забыть."
L["Return picked"] = "Вернуть выбранные"
L["Sends the ticked letters back to whoever sent them. It asks first."] = "Отправляет отмеченные письма назад отправителям. Сначала спрашивает."
L["Tidy up"] = "Прибраться"
L["Throws away read letters that hold nothing at all: no attachment, no coin, nothing owed. It asks first."] = "Выбрасывает прочитанные письма, в которых нет ничего: ни вложений, ни монет, ни долга. Сначала спрашивает."
L["A searchable list of your bags. Click an item to put it on the letter."] = "Список ваших сумок с поиском. Нажмите на предмет, чтобы положить его в письмо."
L["|cffff8800%d cash on delivery|r"] = "|cffff8800с наложенным платежом: %d|r"
L["|cffff3333%d expire within %d days|r"] = "|cffff3333%d истекают в течение %d дн.|r"
L["Forward"] = "Переслать"
L["Forward this letter"] = "Переслать это письмо"
L["Its text goes to the name you give. Attachments come to your bags and are put back on the new letter, so look it over before you press Send."] = "Его текст уйдёт указанному имени. Вложения придут вам в сумки и будут снова вложены в новое письмо, так что проверьте его, прежде чем нажать «Отправить»."
L["this visit: %s and %d items."] = "за этот визит: %s и предметов: %d."
L["Open All takes the coins too"] = "«Открыть всё» забирает и монеты"
L["Off, it collects the attachments and leaves the gold where it is."] = "Если выключено, собирает вложения и оставляет золото на месте."
L["Never open a cash on delivery letter"] = "Никогда не открывать письма с наложенным платежом"
L["Those cost money to accept, so Open All walks past them."] = "Их принятие стоит денег, поэтому «Открыть всё» их пропускает."
L["Leave unread letters alone"] = "Не трогать непрочитанные письма"
L["Open All only empties the letters you have already read."] = "«Открыть всё» опустошает только уже прочитанные письма."
L["Show the summary line"] = "Показывать строку сводки"
L["Warn about letters running out of time"] = "Предупреждать о письмах, у которых кончается срок"
L["Letters with less than three days left are counted in red."] = "Письма, которым осталось меньше трёх дней, считаются красным."
L["Print what the visit was worth"] = "Сообщать, что принёс визит"
L["Address Book button"] = "Кнопка адресной книги"
L["Remember who you write to"] = "Запоминать, кому вы пишете"
L["Recent names on the bar"] = "Недавние имена на панели"
L["Tick boxes on the letters"] = "Галочки на письмах"
L["For Return picked and Tidy up. Tidy up only throws away read letters that hold nothing at all."] = "Для «Вернуть выбранные» и «Прибраться». «Прибраться» выбрасывает только прочитанные письма, в которых нет совсем ничего."
L["Attach from bags button"] = "Кнопка «Вложить из сумок»"
L["Forward button on an open letter"] = "Кнопка «Переслать» на открытом письме"
L["Explain the buttons when the mouse is over them"] = "Объяснять кнопки при наведении мыши"
L["The bar sits under the mailbox window. Open All takes one letter at a time, a third of a second apart: mail sent to the server in a burst is partly dropped, and a dropped take leaves the letter sitting there."] = "Панель находится под окном почты. «Открыть всё» забирает по одному письму с интервалом в треть секунды: почта, отправленная на сервер пачкой, частично теряется, и потерянное письмо остаётся лежать."
L["Copy to all, in the Address Book, sends the letter's subject and text to every name on the list. Attachments exist once and are never copied."] = "«Копия всем» в адресной книге отправляет тему и текст письма каждому имени в списке. Вложения существуют в одном экземпляре и никогда не копируются."
L["%s, %d names in the book. /oxmail all collects, /oxmail book opens it."] = "%s, имён в книге: %d. /oxmail all собирает, /oxmail book открывает книгу."
L["you are not in a group"] = "вы не в группе"
L["you are not the leader or an assistant"] = "вы не лидер и не помощник"
L["you have nothing targeted"] = "у вас нет цели"
L["all three bars are switched off"] = "все три панели выключены"
L["the bars are hidden because %s. Change that in Options, or type /oxmark."] = "панели скрыты, потому что %s. Измените это в настройках или введите /oxmark."
L["Point"] = "Точка"
L["Mark %d"] = "Метка %d"
L["Puts this mark on your target."] = "Ставит эту метку на вашу цель."
L["Clear the mark"] = "Снять метку"
L["Takes the mark off your target."] = "Снимает метку с вашей цели."
L["World marker %d"] = "Маркер на земле %d"
L["Left click puts this flare where you are standing, right click takes it away. "] = "ЛКМ ставит этот огонь там, где вы стоите, ПКМ убирает его. "
L["Dimmed means the game will refuse it: world markers need a real group, and in a raid "] = "Тусклый значит, что игра откажет: маркерам на земле нужна настоящая группа, а в рейде "
L["the leader or an assistant. A follower dungeon does not count, since its companions are NPCs."] = "лидер или помощник. Подземелье с соратниками не считается, ведь соратники это НИП."
L["Clear the flares"] = "Убрать огни"
L["Takes every world marker off the ground. A real group, and lead or assist, again."] = "Убирает все маркеры с земли. Опять же нужна настоящая группа и лидер или помощник."
L["Asks the group whether everyone is ready."] = "Спрашивает группу, все ли готовы."
L["only the leader or an assistant can do that."] = "это может только лидер или помощник."
L["Asks everyone to name their role again."] = "Просит всех заново выбрать роль."
L["Countdown"] = "Отсчёт"
L["Left click starts the pull timer, right click the short one, shift click stops it."] = "ЛКМ запускает таймер пулла, ПКМ короткий, Shift+клик останавливает."
L["Raid marks"] = "Рейдовые метки"
L["Skull, cross and the rest, for your target."] = "Череп, крест и остальные, для вашей цели."
L["World marks"] = "Метки на земле"
L["The eight coloured flares on the ground."] = "Восемь цветных огней на земле."
L["Ready check, role check and countdown"] = "Проверка готовности, проверка ролей и отсчёт"
L["Lock the bars in place"] = "Закрепить панели"
L["Unlocked, drag a bar by any of its buttons. A plain click still marks."] = "Если не закреплено, тащите панель за любую её кнопку. Обычный щелчок по-прежнему ставит метку."
L["Show the panel behind the buttons"] = "Фон за кнопками"
L["Panel opacity"] = "Прозрачность фона"
L["Tooltips"] = "Подсказки"
L["Button size"] = "Размер кнопки"
L["Buttons in a row"] = "Кнопок в ряду"
L["Hide while you are on your own"] = "Скрывать, когда вы один"
L["On, the bars only appear once you are in a group. Off, they are always there."] = "Если включено, панели появляются, только когда вы в группе. Если выключено, они всегда на экране."
L["Hide when you may not mark"] = "Скрывать, когда вам нельзя ставить метки"
L["In a raid the marks only work for the leader and assistants."] = "В рейде метки работают только у лидера и помощников."
L["Show the marks only with a target"] = "Показывать метки только при наличии цели"
L["Countdown, left click"] = "Отсчёт, ЛКМ"
L["Countdown, right click"] = "Отсчёт, ПКМ"
L["Nothing on screen? One of the three boxes above is hiding the bars. /oxmark show turns all three off."] = "Ничего нет на экране? Одна из трёх галочек выше скрывает панели. /oxmark show выключает все три."
L["A world marker goes down where you stand: left click sets it, right click clears that one, and the last button clears them all. The game refuses all of it outside a group, and in a raid for anyone who is neither the leader nor an assistant."] = "Маркер на земле ставится там, где вы стоите: ЛКМ ставит, ПКМ убирает этот маркер, последняя кнопка убирает все. Игра отказывает в этом вне группы, а в рейде всем, кто не лидер и не помощник."
L["Shift click the countdown to stop one that is running."] = "Shift+клик по отсчёту останавливает уже идущий."
L["The buttons are secure ones, which the game will not let an addon show or hide during a fight: a bar that should appear or disappear does so the moment combat ends."] = "Кнопки защищённые, и игра не даёт аддону показывать или скрывать их в бою: панель, которая должна появиться или исчезнуть, сделает это, как только бой закончится."
L["bars locked."] = "панели закреплены."
L["bars unlocked, drag them where you like."] = "панели разблокированы, тащите их куда нужно."
L["every bar is on screen now; the hiding rules are off."] = "все панели теперь на экране; правила скрытия выключены."
L["click tracing on: press a marker button."] = "трассировка щелчков включена: нажмите кнопку метки."
L["click tracing off."] = "трассировка щелчков выключена."
L["bars put back where they started."] = "панели возвращены на исходные места."
