L["|cff0091edSmartMD:|r |cffff4040Macro slots are full.|r Please delete an unused macro and retry."] = "|cff0091edSmartMD:|r |cffff4040Ячейки макросов заполнены.|r Удалите ненужный макрос и попробуйте снова."
L["|cffff4040Note: Smart Misdirect is designed specifically for Hunters (Misdirection) and Rogues (Tricks of the Trade). On this character, the settings can be previewed.|r"] = "|cffff4040Примечание: Smart Misdirect сделан для охотников (Перенаправление) и разбойников (Маленькие хитрости). На этом персонаже настройки можно только посмотреть.|r"
L["Automatically retargets Misdirection & Tricks of the Trade to your party/raid tank or focus with a 1-click secure macro."] = "Автоматически перенаправляет Перенаправление и Маленькие хитрости на танка группы/рейда или фокус макросом в один клик."
