L["Icons per arm"] = "Значков на луч"
L["Rows: the arrows send each group its own way. Spiral: each group is an arm. Edit the arms, then drag its points; Shift-click a point adds one after it, Ctrl-click removes it, right-click resets the arm. While editing, drag a teleport onto another arm to move it there. Left-click an icon to travel, right-click to put it away. Shift-drag moves a locked button."] = "Ряды: стрелки отправляют каждую группу в свою сторону. Спираль: каждая группа это луч. Нажмите «Изменить лучи» и тащите точки; Shift+клик по точке добавляет следующую, Ctrl+клик убирает, ПКМ сбрасывает луч. Во время правки перетащите телепорт на другой луч, чтобы перенести его. ЛКМ по значку, чтобы переместиться, ПКМ, чтобы убрать. Shift+перетаскивание двигает закреплённую кнопку."
L["sample bars on. They go off when a fight starts, or type /oxthreat test again."] = "пример полос включён. Он выключится в начале боя, или снова введите /oxthreat test."
L["Damage"] = "Урон"
L["Fade green to red"] = "Плавно от зелёного к красному"
L["Damage colours run smoothly with the percentage. Off, they step from green to yellow to orange to red."] = "Цвета для урона плавно меняются с процентом. Если выключено, ступенями: зелёный, жёлтый, оранжевый, красный."
L["Round the ends"] = "Скруглённые концы"
L["Name whoever is holding it"] = "Называть, кто держит агро"
L["Under the bar, in their class colour."] = "Под полосой, в цвете его класса."
L["Distance below the plate"] = "Отступ под индикатором"
L["Warn from"] = "Предупреждать с"
L["Flash the bar"] = "Мигание полосы"
L["Glow around the nameplate"] = "Свечение вокруг индикатора"
L["Warning sound when you take it"] = "Звук предупреждения, когда агро на вас"
L["A raid warning the moment your threat passes whoever is holding the enemy. Silent while the game hides the numbers."] = "Рейдовое предупреждение в момент, когда ваша угроза обгоняет того, кто держит врага. Молчит, пока игра скрывает цифры."
L["Only enemies in combat"] = "Только враги в бою"
L["Work with Platynator and other nameplate addons"] = "Работа с Platynator и другими аддонами индикаторов"
L["When another addon hides the game's nameplates, the bar sits under that addon's health bar instead."] = "Когда другой аддон скрывает индикаторы игры, полоса располагается под его полосой здоровья."
L["Only in a group"] = "Только в группе"
L["On your own there is nobody to take the enemy from."] = "В одиночку агро отбирать не у кого."
L["Bar width 0 follows the nameplate's own width. Type /oxthreat test for sample bars while you set the look."] = "Ширина 0 повторяет ширину индикатора. Введите /oxthreat test для примера полос во время настройки."
L["In a fight the game keeps the exact threat from addons. The colours, the flash and the glow keep working anyway: each one is a bar whose range is a hair wide, so the game itself decides whether it is empty or full. Only the printed number and the sound need reading it, and those are the parts that go quiet."] = "В бою игра скрывает точную угрозу от аддонов. Цвета, мигание и свечение всё равно работают: каждое из них это полоса с крошечным диапазоном, и игра сама решает, пуста она или полна. Только напечатанное число и звук требуют чтения значения, и они затихают."
L["Copy with Ctrl+C:"] = "Скопируйте Ctrl+C:"
L["Click: show it on the map."] = "Щелчок: показать на карте."
L["Click: open it. Shift-click: link in chat. Right-click: web link."] = "Щелчок: открыть. Shift+клик: ссылка в чат. ПКМ: веб-ссылка."
L["Shift-click: link in chat. Right-click: web link."] = "Shift+клик: ссылка в чат. ПКМ: веб-ссылка."
L["|cff9d9d9dLooking at the world quests...|r"] = "|cff9d9d9dСмотрим локальные задания...|r"
L["|cff9d9d9dNothing up right now that you still need. Try All expansions, or Show all.|r"] = "|cff9d9d9dСейчас нет ничего нужного вам. Попробуйте «Все дополнения» или «Показать все».|r"
L["%d quest(s)"] = "Заданий: %d"
