-- ============================================================================
L["Buff Reminder"] = "Напоминание о баффах"
L["Before a Mythic+ key starts, under"] = "До старта ключа М+, меньше"
L["%s %d min (0 = off)"] = "%s %d мин (0 = выкл.)"
L["Only on a ready check"] = "Только при проверке готовности"
L["The bar stays hidden the rest of the time and shows for 30 seconds when a ready check starts."] = "Всё остальное время полоса скрыта и появляется на 30 секунд, когда начинается проверка готовности."
L["Wait 30 seconds before asking again"] = "Ждать 30 секунд перед повторной просьбой"
L["Untick if a request seems not to arrive and you want to send it again at once."] = "Снимите, если просьба будто бы не доходит и вы хотите сразу отправить её снова."
L["Only check yourself"] = "Проверять только себя"
L["The group buff icon shows only when you lack it, not when somebody else in the group does."] = "Значок группового баффа появляется, только когда его нет у вас, а не у кого-то в группе."
L["...but those only on a ready check"] = "...но такие только при проверке готовности"
L["Leave out items from older expansions"] = "Не предлагать предметы из прошлых дополнений"
L["Food, flasks and oil from a past expansion get no icon, even when they are in your bags."] = "Еда, настои и масла из прошлых дополнений не получают значок, даже если они в сумках."
L["Only delve food in delves"] = "В вылазках только еда для вылазок"
L["Delve food reminder gives up after 30 seconds"] = "Напоминание о еде для вылазок пропадает через 30 секунд"
L["Healthstone reminder at or below"] = "Камень здоровья, если зарядов не больше"
L["%s %d charges"] = "%s %d"
L["A click on the repair icon summons your Grand Expedition Yak or Mighty Caravan Brutosaur, or uses an Auto-Hammer or Jeeves, whichever you have."] = "Щелчок по значку ремонта призывает Большого яка для путешествий или Могучего караванного брутозавра либо использует Автомолот или Дживса, смотря что у вас есть."
L["Demons wanted, per content"] = "Нужные демоны по видам контента"
L["The ticked demons come first when yours is missing. Turn on \"Not one of your demons for this content\" in Reminders to be told when another one is out. Demonology always wants its Felguard."] = "Отмеченные демоны идут первыми, когда вашего нет. Включите «Не тот демон для этого контента» в напоминаниях, чтобы узнавать, когда призван другой. Демонологии всегда нужен Страж Скверны."
L["Fel Domination before a summon"] = "Господство Скверны перед призывом"
L["A click on a demon icon casts Fel Domination first, so the demon arrives at once."] = "Щелчок по значку демона сначала применяет Господство Скверны, и демон появляется сразу."
L["Soulstone always goes on"] = "Камень души всегда на"
L["A player's name, with the realm when it is not yours. Empty: whoever had it last, else the healer."] = "Имя игрока, с сервером, если он не ваш. Пусто: на того, у кого был в прошлый раз, иначе на лекаря."
