-- ============================================================================
-- Frame Mover, AddOn Manager and mix keybinds.
-- ============================================================================
L["Drag the game's windows anywhere and they open there again. Ctrl+wheel resizes. /oxmove"] = "Перетаскивайте окна игры куда угодно, они откроются там же. Ctrl+колёсико меняет размер. /oxmove"
L["Remember where each window was"] = "Запоминать, где было каждое окно"
L["Off: a moved window goes back to its usual place when you close it."] = "Выключено: перемещённое окно возвращается на обычное место, когда вы его закрываете."
L["Ctrl + mouse wheel resizes a window"] = "Ctrl + колёсико мыши меняет размер окна"
L["Keep windows on the screen"] = "Не выпускать окна за край экрана"
L["Put every window back"] = "Вернуть все окна на место"
L["windows can be put back after the fight."] = "окна можно вернуть на место после боя."
L["every window is back in its usual place."] = "все окна снова на обычных местах."
L["Drag a window by an empty part of it, such as its title or border. Protected windows (spellbook, talents and some others) cannot be moved during a fight. /oxmove reset puts every window back."] = "Тащите окно за пустую часть, например за заголовок или рамку. Защищённые окна (книга заклинаний, таланты и некоторые другие) нельзя двигать в бою. /oxmove reset возвращает все окна на место."
L["Frame Mover"] = "Перемещение окон"
L["Keybinds"] = "Клавиши"
L["Mix keybinds"] = "Клавиши миксов"
L["Press a key to run a mix, no ActionHub needed. /oxmixkeys"] = "Запускайте микс клавишей, без ActionHub. /oxmixkeys"
L["Click a key box, then press the key. Escape cancels, right-click clears."] = "Нажмите на поле клавиши, затем нужную клавишу. Escape отменяет, ПКМ стирает."
L["Press a key..."] = "Нажмите клавишу..."
L["keys can be changed after the fight."] = "клавиши можно менять после боя."
L["No mixes yet. Make one in the Mixer first."] = "Миксов пока нет. Сначала создайте микс в микшере."
L["AddOn Manager"] = "Менеджер аддонов"
L["Addons grouped, searchable, switched per character, with saved sets. /oxaddons"] = "Аддоны по группам, с поиском, для персонажа или всех, с наборами. /oxaddons"
L["Loaded"] = "Загружен"
L["Off"] = "Выкл."
L["On demand"] = "По запросу"
L["Reload needed"] = "Нужна перезагрузка"
L["Sets"] = "Наборы"
L["Saved sets"] = "Сохранённые наборы"
L["Switch to this set"] = "Переключиться на этот набор"
L["Save the current list here"] = "Сохранить сюда текущий список"
L["No sets yet"] = "Наборов пока нет"
L["Save the current list as a new set..."] = "Сохранить текущий список как новый набор..."
L["New set name:"] = "Название набора:"
L["Needs: "] = "Требует: "
L["Memory: %.1f MB"] = "Память: %.1f МБ"
L["All on"] = "Всё вкл."
L["All off"] = "Всё выкл."
L["Reload UI"] = "Перезагрузить"
L["%d of %d addons on"] = "Включено аддонов: %d из %d"
L["Reload to apply the changes."] = "Перезагрузите, чтобы применить изменения."
L["switch the AddOn Manager module on first (/ohub > Modules)."] = "сначала включите модуль AddOn Manager (/ohub > Модули)."
L["Switch addons for every character"] = "Включать и выключать аддоны для всех персонажей"
L["Off: a change applies to the character you are playing only."] = "Выключено: изменение касается только текущего персонажа."
L["Type /oxaddons to open the list. A plugin is listed under the addon it needs, and addons that share a name, like DBM- or BigWigs_, are kept together. OxedHub itself is never switched off by All off or a set."] = "Список открывается командой /oxaddons. Плагин показывается под аддоном, который ему нужен, а аддоны с общим началом названия, как DBM- или BigWigs_, держатся вместе. Сам OxedHub никогда не выключается кнопкой «Всё выкл.» или набором."

